document.addEventListener("click",async s=>{const t=s.target.closest("[data-vote]");if(!t)return;const a=t.dataset.type,o=t.dataset.id,c=parseInt(t.dataset.vote,10),r=document.querySelector(`[data-score="${a}-${o}"]`);try{const e=await fetch("/api/vote.php",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({type:a,id:o,value:c,csrf_token:window.CSRF_TOKEN})}),n=await e.json();if(!e.ok){alert(n.error||"Vote failed.");return}r&&(r.textContent=n.score)}catch(e){alert("Network error, please try again.")}});
